const deadline=setTimeout(()=>{console.error("overall240second timeout");process.exit(2)},240000);
const {chromium}=require('/Users/ahimanikya/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
const fs=require('fs'),path=require('path'),assert=require('assert');
const crypto=require('crypto'),cp=require('child_process');const repo=process.cwd(),story=JSON.parse(fs.readFileSync(path.join(repo,'kb/research/food/collection.json'))).pages.find(p=>p.slug==='baigana-poda'),editorial=JSON.parse(fs.readFileSync(path.join(repo,'kb/research/food/baigana-poda-editorial.json'))),base=process.argv[2],out=path.resolve(process.argv[3]||'');
if(process.env.RUN_AUTHORIZED_BAIGANA_LIVE!=='1')throw Error('Live execution not authorized');
assert(base==='https://projectodisha.org','Exact public origin required');assert(process.argv[3]&&process.argv[4],'Unique output and root authorization JSON required');
const authorization=JSON.parse(fs.readFileSync(process.argv[4]));assert(authorization.status==='SUCCESS'&&authorization.live_go===true&&/^[a-f0-9]{40}$/.test(authorization.merge_commit)&&/^\d+$/.test(String(authorization.run_id)),'Actual root deployment SUCCESS authorization required');
assert(!fs.existsSync(out),'Refuse overwrite prior run');
const expected=JSON.parse(fs.readFileSync(path.join(__dirname,'expected-inputs.json')));for(const b of expected.bindings){const raw=fs.readFileSync(b.path);assert.equal(raw.length,b.bytes);assert.equal(crypto.createHash('sha256').update(raw).digest('hex'),b.sha256,'Expected input drift: '+b.path);}
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
const foods=JSON.parse(fs.readFileSync(path.join(repo,'kb/research/food/collection.json'))),photo=foods.assets[story.hero];
(async()=>{fs.mkdirSync(out,{recursive:true});const browser=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true,timeout:15000});const results=[],http=[];const httpContext=await browser.newContext();for(const slug of ['baigana-poda','fire-cooking']){const response=await httpContext.request.get(base+'/food/'+slug+'/',{timeout:15000,maxRedirects:3});assert.equal(response.status(),200);assert.equal(new URL(response.url()).origin,base);const bytes=await response.body();fs.writeFileSync(path.join(out,slug+'-response.html'),bytes);const expectedPath=path.join(repo,'projects/site/dist-publish/food',slug,'index.html');http.push({url:response.url(),status:response.status(),headers:response.headers(),sha256:hash(bytes),bytes:bytes.length,local_sha256:hash(fs.readFileSync(expectedPath)),exact_local:hash(bytes)===hash(fs.readFileSync(expectedPath))});}await httpContext.close();fs.writeFileSync(path.join(out,'http-results.json'),JSON.stringify(http,null,2));
for(const [name,width,height] of [['desktop',1440,900],['phone',390,844]]){const context=await browser.newContext({viewport:{width,height},acceptDownloads:true});const page=await context.newPage();page.setDefaultTimeout(10000);page.setDefaultNavigationTimeout(15000);await page.goto(base+'/food/baigana-poda/',{waitUntil:'networkidle'});await page.evaluate(()=>document.fonts.ready);const catalog=await page.locator('#journey-data').textContent();const parent=JSON.parse(catalog).catalog.find(x=>x.id==='reading:food/fire-cooking');assert.deepEqual(parent,JSON.parse(fs.readFileSync(expected.bindings[2].path)));fs.writeFileSync(path.join(out,name+'-parent.json'),JSON.stringify(parent,null,2));assert.equal(await page.evaluate(()=>innerWidth),width);assert.equal(await page.evaluate(()=>innerHeight),height);const hero=page.locator('.mag-cover img');await hero.evaluate(async image=>{if(!image.complete)await new Promise(r=>image.addEventListener('load',r,{once:true}));await image.decode();});const imageState=await hero.evaluate(i=>({src:i.getAttribute('src'),currentSrc:i.currentSrc,naturalWidth:i.naturalWidth,naturalHeight:i.naturalHeight,alt:i.alt}));assert(imageState.naturalWidth>0);assert.equal(imageState.alt,photo.alt);await page.screenshot({path:path.join(out,name+'-opening.png')});await page.screenshot({path:path.join(out,name+'-full-body.png'),fullPage:true});assert.equal(await page.locator('h1').evaluate(h=>{const c=h.cloneNode(true);c.querySelectorAll('[lang=or],.odia').forEach(n=>n.remove());return c.textContent.trim();}),story.title);const rendered=await page.locator('article p[data-source-ids]').evaluateAll(nodes=>nodes.map(node=>{const copy=node.cloneNode(true);copy.querySelectorAll('sup').forEach(n=>n.remove());return copy.textContent.trim();}));assert.deepEqual(rendered,story.sections.flatMap(s=>s.paragraphs.map(p=>p.text)));assert.equal(await page.locator('article sup a').count(),story.sections.flatMap(s=>s.paragraphs).reduce((n,p)=>n+p.source_ids.length,0));let returns=0;
for(const id of await page.locator('article sup a').evaluateAll(a=>a.map(e=>e.id))){const link=page.locator('[id="'+id+'"]');const target=await link.getAttribute('href');await link.focus();await page.keyboard.press('Enter');await page.waitForTimeout(80);assert.equal(await page.evaluate(()=>location.hash),target);const back=page.locator('a[href="#'+id+'"]').last();await back.focus();await page.keyboard.press('Enter');await page.waitForTimeout(80);assert.equal(await page.evaluate(()=>location.hash),'#'+id);returns++;}
await page.locator('#story-sources').scrollIntoViewIfNeeded();await page.screenshot({path:path.join(out,name+'-sources.png')});assert.equal(await page.locator('#food-further-reading details').count(),0);for(const link of [...story.related,{href:'/journey/'}])assert(await page.locator('#food-further-reading a[href=\"'+link.href+'\"]').count());const metrics=await page.evaluate(()=>({width:innerWidth,scrollWidth:document.documentElement.scrollWidth}));assert(metrics.scrollWidth<=width);const save=page.locator('[data-save-journey="food:baigana-poda"]');await save.click();await page.reload({waitUntil:'networkidle'});assert.match(await save.textContent(),/Saved/);await page.goto(base+'/journey/',{waitUntil:'networkidle'});assert((await page.locator('body').innerText()).includes(story.title));const downloadPromise=page.waitForEvent('download',{timeout:15000});await page.locator('#illustrated-book').click();const download=await downloadPromise;const file=path.join(out,name+'-reading.html');await download.saveAs(file);const html=fs.readFileSync(file,'utf8');assert(html.includes(photo.creator));assert(html.includes(photo.license_url));assert(/data:image\//.test(html));assert(!/<h4>\s*<\/h4>/.test(html));const parse=await context.newPage();await parse.goto('file://'+file);const portable=await parse.locator('body').innerText();assert(html.includes(base+'/food/baigana-poda/'));assert(!html.includes('127.0.0.1:'));assert.equal(await parse.locator('h4:empty').count(),0);for(const p of story.sections.flatMap(s=>s.paragraphs.map(p=>p.text)))assert(portable.includes(p));for(const s of editorial.portable_sources)for(const link of [{text:s.title,href:s.url}]){assert(portable.includes(link.text));assert(html.includes(new URL(link.href).href.replaceAll('&','&amp;')));}
const pendingText=page.waitForEvent('download',{timeout:15000});await page.locator('#plain-itinerary').click();const textDownload=await pendingText;const textFile=path.join(out,name+'-reading.txt');await textDownload.saveAs(textFile);const textBody=fs.readFileSync(textFile,'utf8');assert(textBody.includes(base+'/food/baigana-poda/'));assert(!textBody.includes('127.0.0.1:'));assert(!textBody.includes(': '+story.sections[0].paragraphs[0].text));for(const p of story.sections.flatMap(s=>s.paragraphs))assert.equal(textBody.split(p.text).length-1,1);for(const source of editorial.portable_sources)for(const link of [{text:source.title,href:source.url}]){assert(textBody.includes(link.text));assert(textBody.includes(new URL(link.href).href));}results.push({actualTextDownload:textFile,threeParagraphsOnce:true,threeShortSources:true,name,imageState,viewport:{width,height},metrics,keyboardNoteReturns:returns,saveReload:true,actualOfflineDownload:file,allParagraphsAndShortSources:true});await context.close();}
await browser.close();fs.writeFileSync(path.join(out,'browser-review.json'),JSON.stringify({status:'PASS',authorization,http,checked_at:new Date().toISOString(),tested_head:cp.execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),working_tree_basis:'Checkout head identifies reviewed local inputs; actual deployed merge/run come from root SUCCESS authorization and live evidence. Shell hash differences are reported, not silently treated as byte equality.',article_source_sha256:crypto.createHash('sha256').update(fs.readFileSync(path.join(repo,'kb/research/food/baigana-poda-editorial.json'))).digest('hex'),base,browser:'Actual headless Google Chrome',results,limits:['Not assistive-technology testing or Firefox/WebKit.']},null,2));clearTimeout(deadline);console.log('PASS public desktop/phone, all keyboard returns,save/reload,actual downloads');})().catch(e=>{if(fs.existsSync(out))fs.writeFileSync(path.join(out,'failure.json'),JSON.stringify({status:'FAIL',checked_at:new Date().toISOString(),error:String(e),stack:e.stack},null,2));console.error(e);process.exit(1)});

